import {escapeHtml as e} from './domain.js';
import {methodConfig,blockDay,currentDay} from './study-method.js';
import {syllabusKey} from './cycle-plan.js';
import {planLabel,durationText,visibleSteps,dayTasks,reviewHasCards,flashScore,sessionClock} from './study-state.js';
export function createStudySpace(ctx){
 const {state,api,notify,renderView,heading,field,area,select,badge,empty,profilePick,admin,premium,guardWrite,loadData}=ctx;
 let session=null,syncedAt=0,busy=false,lastTick=0,run=null,revealed=false,cardEdit=null;
 const data=t=>state.data[t]||[];
 const btn=(label,action,attrs='',style='small')=>`<button type="button" class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
 const cycles=()=>data('cycles').filter(c=>c.student_id===state.profile.id&&c.status==='Publicado').sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
 const learnerCycle=()=>cycles().find(c=>c.id===state.boardCycle)||cycles()[0];
 const getStudy=(c,b)=>data('method_studies').find(s=>s.cycle_id===c.id&&s.block_id===b.id);
 function modal(title,html){document.querySelector('#study-dialog')?.remove();const el=document.createElement('dialog');el.id='study-dialog';el.className='study-dialog';el.setAttribute('aria-label',title);el.innerHTML=`<header class="dialog-header"><h2>${e(title)}</h2>${btn('Fechar','study-close')}</header><div id="dialog-notice" role="status"></div><div class="dialog-body">${html}</div>`;document.body.append(el);el.showModal?.();if(!el.showModal)el.setAttribute('open','');}
 function restore(){if(!state.profile)return;const saved=data('study_sessions').find(s=>s.student_id===state.profile.id&&s.status!=='ended');if(saved&&saved.id!==session?.id){session={...saved,status:'paused'};syncedAt=Date.now();}if(session&&session.student_id!==state.profile.id)session=null;}
 function progress(c){const tasks=dayTasks(c,state.data),done=tasks.filter(t=>t.done).length,day=currentDay(c,data('progress')),logs=data('study_logs').filter(l=>l.cycle_id===c.id&&l.plan_day===day),minutes=logs.reduce((s,l)=>s+Number(l.minutes||0),0),questions=logs.reduce((s,l)=>s+l.total,0);return `<section class="day-overview"><div class="row"><h3>${planLabel(day)}</h3>${badge(done===tasks.length?'Dia concluído':`${done} de ${tasks.length} tarefas concluídas`,done===tasks.length?'green':'')}</div><progress max="${Math.max(1,tasks.length)}" value="${tasks.length?done:1}" aria-label="Progresso do dia"></progress><p>${durationText(minutes*60)} estudado neste dia do plano · ${questions} questões</p>${done===tasks.length?btn('AVANÇAR PARA O PRÓXIMO DIA','study-advance',`data-cycle="${c.id}"`,'primary'):'<p class="muted">Conclua as atividades e revisões pendentes para liberar o próximo dia.</p>'}</section>`;}
 function topicCard(c,b){const study=getStudy(c,b),steps=visibleSteps(c,b,state.data),done=steps.filter(s=>study?.flags?.[s.id]).length,secs=data('study_sessions').filter(s=>s.cycle_id===c.id&&s.block_id===b.id).reduce((a,s)=>a+Number(s.focused_seconds),0);return `<article class="study-task topic-study"><span class="task-kicker">${e(b.subject)}</span><strong>${e(b.topic)}</strong><span>${done} / ${steps.length} etapas · ${durationText(secs)}</span>${badge(done===steps.length?'Concluído':study||secs?'Em andamento':'Não iniciado',done===steps.length?'green':'')}<p class="muted">${e(methodConfig(b.method).priority)} prioridade · ${methodConfig(b.method).initial_questions} questões</p>${btn('ESTUDAR','study-open',`data-cycle="${c.id}" data-block="${e(b.id)}"`,'primary')}</article>`;}
 function dashboard(){const c=learnerCycle();if(!c)return empty('Seu plano está sendo preparado','Quando o mentor publicar o ciclo, a próxima atividade aparecerá aqui.');const tasks=dayTasks(c,state.data),unique=[...new Map(tasks.filter(t=>t.b).map(t=>[t.b.id,t.b])).values()],reviews=tasks.filter(t=>t.r),first=tasks.find(t=>!t.done),next=first?(first.b?topicCard(c,first.b):reviewTask(first)):'';return progress(c)+(next?`<section class="next-study"><span class="eyebrow">Continue de onde parou</span><h2>Sua próxima atividade</h2>${next}</section>`:'')+`<div class="section-head compact"><div><span class="eyebrow">Organização do dia</span><h2>Plano do dia</h2></div><a class="btn small" href="#painel/ciclos">Ver plano completo</a></div><div class="review-grid">${unique.map(b=>topicCard(c,b)).join('')}${reviews.map(t=>reviewTask(t)).join('')}</div>`;}
 function reviewTask(t){const s=data('method_studies').find(s=>s.id===t.r.study_id);return `<article class="study-task review"><small>${e(s?.subject)}</small><strong>${e(s?.topic)}</strong>${badge(t.done?'Concluída':t.flash?'FLASHCARDS':'REVISÃO',t.done?'green':'')}<span>${t.flash?'Recorde o assunto e confira as respostas':t.r.questions+' questões'}</span>${btn(t.flash?'Revisar flashcards':'Abrir revisão',t.flash?'flash-start':'open-review',`data-id="${t.r.id}" data-review="${t.r.id}"`)}</article>`;}
 async function open(c,b){if(blockDay(b,c)>currentDay(c,data('progress')))throw Error('Conclua o dia atual para liberar este assunto.');restore();if(session&&session.status!=='ended'&&session.cycle_id===c.id&&session.block_id===b.id){state.studyTarget={cycle:c.id,block:b.id};showWorkspace();return;}
 if(session&&session.status!=='ended'){modal('Você tem um estudo em andamento',`<p>${e(session.subject)} · ${e(session.topic)}</p>${btn('Retomar estudo','study-return','','primary')}${btn('Encerrar sessão atual','timer-end')}`);return;}
 state.studyTarget={cycle:c.id,block:b.id};modal('Quanto tempo pretende estudar?',`<p>${e(b.subject)} · ${e(b.topic)}</p><form id="study-start-form" class="fields">${select('Duração','duration',[[30,'30 minutos'],[45,'45 minutos'],[60,'1 hora'],[90,'1h30'],[120,'2 horas'],['custom','Personalizada']],[30,45,60,90,120].includes(b.minutes)?b.minutes:'custom')}${field('Duração personalizada (minutos)','custom','number',b.minutes||60,'min="1" max="960"')}${field('Foco (minutos)','focus','number',25,'required min="1" max="120"')}${field('Descanso (minutos, 0 para contínuo)','rest','number',5,'required min="0" max="30"')}<button class="primary">Abrir tela de estudo</button></form>`);notify('Escolha o tempo e os intervalos.','info');}
 function showWorkspace(){document.querySelector('#study-dialog')?.remove();state.view='estudo';history.pushState(null,'','#painel/estudo');renderView();notify('Tela do assunto aberta.','info');}
 function page(){restore();const target=state.studyTarget||(session?{cycle:session.cycle_id,block:session.block_id}:null),c=data('cycles').find(c=>c.id===target?.cycle),b=c?.blocks.find(b=>b.id===target?.block);if(!b)return heading('Estudar')+empty('Abra um assunto pelo seu plano');const cfg=methodConfig(b.method),s=getStudy(c,b),steps=visibleSteps(c,b,state.data),done=steps.filter(x=>s?.flags?.[x.id]).length;return heading(e(b.subject)+' · '+e(b.topic),planLabel(blockDay(b,c))+' · '+cfg.priority+' prioridade',btn('Ver plano','study-back'))+`<div class="study-workspace"><aside class="card timer-panel"><span class="eyebrow">Pomodoro do assunto</span>${session&&session.cycle_id===c.id&&session.block_id===b.id?timerHTML():btn('Definir novo tempo','study-open',`data-cycle="${c.id}" data-block="${e(b.id)}"`,'primary')}<p class="muted">O descanso fica separado do tempo estudado. Sem conexão, o relógio pausa até você continuar.</p></aside><div class="stack"><section class="card"><div class="row"><h2>Seu estudo</h2>${badge(done===steps.length?'Concluído':s||session?'Em andamento':'Não iniciado',done===steps.length?'green':'')}</div><progress max="${Math.max(1,steps.length)}" value="${done}" aria-label="Etapas do assunto"></progress><p>${done} de ${steps.length} etapas · Mínimo de ${cfg.initial_questions} questões</p>${cfg.notes||b.notes?`<div class="mentor-note"><strong>Observação do mentor</strong><p>${e(cfg.notes)}</p><p>${e(b.notes)}</p></div>`:''}<ol class="study-stage-list">${steps.map((step,i)=>`<li><div><strong>Etapa ${i+1} · ${e(step.title)}</strong><small>${s?.flags?.[step.id]?'Concluída':step.kind==='questions'?cfg.initial_questions+' questões':'Pendente'}</small></div>${btn(step.kind==='flashcard'?'Abrir flashcards':s?.flags?.[step.id]?'Ver registro':'Abrir etapa',step.kind==='flashcard'?'flash-start':'open-study-task',`data-cycle="${c.id}" data-block="${e(b.id)}" data-stage="${e(step.id)}"`)}</li>`).join('')}</ol>${premium()?[cfg.resource_id,cfg.video_id].filter(Boolean).map(id=>{const r=data('resources').find(r=>r.id===id);return r?btn(e(r.kind+': '+r.title),'study-material',`data-id="${id}"`):'';}).join(''):''}${studyMaterial()}<details><summary>Revisões programadas</summary>${data('method_reviews').filter(r=>r.study_id===s?.id&&r.status!=='cancelled').map(r=>`<p>${planLabel(r.due_day)} · ${r.questions} questões · ${r.status==='completed'?'Concluída':'Pendente'}</p>`).join('')||cfg.reviews.map(r=>`<p>+${r.after} dias · ${r.questions} questões</p>`).join('')}</details>${btn('Ver histórico completo do assunto','topic-history',`data-topic="${e(b.topic_key)}" data-student="${c.student_id}"`)}</section>${progress(c)}</div></div>`;}
 function timerHTML(){return `<div id="timer-live"><p id="timer-phase"></p><strong id="timer-remaining" class="clock">00:00:00</strong><p>Restante nesta etapa</p><p>Estudado: <strong id="timer-focused"></strong></p><p>Meta restante: <span id="timer-goal"></span></p></div><p>Programado: ${durationText(session.target_seconds)} · Foco ${session.focus_seconds/60} min / descanso ${session.break_seconds/60} min</p><div id="timer-actions" class="actions">${timerActions()}</div>`;}
 function timerActions(){return session.status==='ended'?`<p>Sessão encerrada e tempo salvo.</p>${btn('Nova sessão','study-open',`data-cycle="${session.cycle_id}" data-block="${e(session.block_id)}"`,'primary')}`:btn(session.status==='running'?'Pausar':session.phase==='break'?'Iniciar descanso':session.focused_seconds?'Continuar':'Iniciar',session.status==='running'?'timer-pause':'timer-resume','','primary')+btn('Encerrar','timer-end');}
 function studyMaterial(){const r=state.studyMaterial;if(!r)return '';let u;try{u=new URL(r.url);}catch{return '';}if(r.kind==='Vídeo'){const id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').at(-1);if(['www.youtube.com','youtube.com','youtu.be'].includes(u.hostname)&&/^[\w-]{11}$/.test(id))return `<iframe class="lesson-video" src="https://www.youtube-nocookie.com/embed/${id}" title="${e(r.title)}" allowfullscreen></iframe>`;if(/\.(mp4|webm)(\?|$)/i.test(r.url))return `<video class="lesson-video" src="${e(r.url)}" controls></video>`;}return `<p>${btn('Abrir material com marca d’água','export-material',`data-id="${r.id}"`)}</p>`;}
 function afterRender(){if(!state.profile)return;restore();document.querySelector('#timer-chip')?.remove();if(session&&session.status!=='ended'){const chip=document.createElement('div');chip.id='timer-chip';chip.innerHTML=btn('Retomar estudo · '+e(session.topic),'study-return');document.body.append(chip);}drawClock();}
 function drawClock(){if(!session)return;const clock=sessionClock(session,Date.now(),syncedAt);for(const [id,value]of Object.entries({'timer-focused':durationText(clock.focused),'timer-remaining':durationText(clock.remaining),'timer-goal':durationText(clock.goal),'timer-phase':(session.phase==='focus'?'Foco':'Descanso')+' · '+({running:'Em andamento',paused:'Pausado',ended:'Encerrado'}[session.status])})){const el=document.getElementById(id);if(el)el.textContent=value;}}
 async function timerCommand(action){if(!session)return;guardWrite();const prev=session.status;session=await api.rpc('study_timer',{payload:{action,session_id:session.id}});syncedAt=Date.now();const i=data('study_sessions').findIndex(s=>s.id===session.id);if(i>=0)state.data.study_sessions[i]=session;else state.data.study_sessions.push(session);if(action!=='tick'||session.status!==prev){await loadData();renderView();notify(session.status==='ended'?'Sessão encerrada. Tempo de foco salvo.':session.status==='paused'?'Cronômetro pausado. Tempo salvo.':'Cronômetro iniciado.','success');}drawClock();}
 async function tick(){drawClock();if(!session||session.status!=='running'||busy||Date.now()-lastTick<10000)return;busy=true;lastTick=Date.now();try{await timerCommand('tick');}catch(err){session={...session,status:'paused'};notify('Cronômetro pausado: '+err.message,'error');const el=document.querySelector('#timer-actions');if(el)el.innerHTML=timerActions();}finally{busy=false;}}
 function flashPage(){if(!premium())return heading('Flashcards')+empty('Recurso do plano Estratégico');const c=learnerCycle();if(!admin()){if(!c||currentDay(c,data('progress'))<8)return heading('Flashcards a partir do Dia 08','Na primeira semana, o foco é construir a base dos assuntos.')+empty('Sua revisão ativa começa na segunda semana','Os cartões serão sempre ligados a conteúdos que você já estudou.');const tasks=dayTasks(c,state.data).filter(t=>t.flash||t.step?.kind==='flashcard');return heading('Flashcards','Revise um assunto por vez. Pense na resposta antes de revelar o verso.')+`<nav class="context-tabs"><a href="#painel/revisoes">Revisões</a><a class="active" href="#painel/flashcards">Flashcards</a><a href="#painel/erros">Caderno de erros</a></nav>`+flashStats(state.profile.id)+`<div class="section-head compact"><div><span class="eyebrow">Fila de hoje</span><h2>${tasks.length?tasks.length+' revisão'+(tasks.length===1?'':'ões'):'Tudo em dia'}</h2></div></div>`+(tasks.map(t=>t.r?reviewTask(t):topicCard(c,t.b)).join('')||empty('Nenhum flashcard programado para este dia','Continue o plano. Os cartões voltarão nas revisões escolhidas pelo mentor.'))+dayHistory(state.profile.id);}
 const card=cardEdit||{},career=state.cardCareer||'CFO',topics=state.topics.filter(t=>t.career===career),subject=state.cardSubject||topics[0]?.subject,scoped=topics.filter(t=>t.subject===subject);const selected=card.topic_key||syllabusKey(scoped[0]||{});const reviewKeys=[...new Set(['r1','r2','r3','r4',...data('method_templates').flatMap(t=>(t.config.reviews||[]).map(r=>r.id)),...data('cycles').flatMap(c=>c.blocks.flatMap(b=>methodConfig(b.method).reviews.map(r=>r.id)))])];return heading('Flashcards','Cada cartão pertence a um assunto do edital. As respostas alimentam o histórico do aluno.')+`<form id="flashcard-form" class="card fields" data-id="${card.id||''}">${select('Concurso','card_career',['CFO','Soldado'],career)}${select('Matéria','card_subject',[...new Set(topics.map(t=>t.subject))],subject)}${select('Assunto específico','topic_key',scoped.map(t=>[syllabusKey(t),t.code+' · '+t.title]),selected)}${area('Frente (pergunta)','front',card.front||'','required maxlength="5000"')}${area('Verso (resposta)','back',card.back||'','required maxlength="10000"')}<div class="full"><strong>Mostrar nas revisões</strong><p class="muted">Ative os flashcards no método do assunto. Eles aparecem nas revisões selecionadas a partir do Dia 08. Etapas próprias usam todos os cartões daquele assunto.</p><div class="check-grid">${reviewKeys.map((id,i)=>`<label><input type="checkbox" name="review_keys" value="${e(id)}" ${(card.review_keys||['r3','r4']).includes(id)?'checked':''}>${/^r[1-4]$/.test(id)?id.slice(1)+'ª revisão':e('Revisão +'+(data('method_templates').flatMap(t=>t.config.reviews||[]).concat(data('cycles').flatMap(c=>c.blocks.flatMap(b=>methodConfig(b.method).reviews))).find(r=>r.id===id)?.after||'?')+' dias')}</label>`).join('')}</div></div><button class="primary">${card.id?'Salvar alterações':'Criar flashcard'}</button>${btn('Limpar formulário','flash-clear')}</form><div class="asset-list">${data('flashcards').map(f=>{const t=state.topics.find(t=>syllabusKey(t)===f.topic_key);return `<article class="card"><small>${e(t?.career)} · ${e(t?.subject)}</small><h3>${e(t?.title)}</h3><p>${e(f.front)}</p><details><summary>Resposta</summary><p>${e(f.back)}</p></details><div class="actions">${btn('Editar','flash-edit',`data-id="${f.id}"`)}${btn('Excluir','flash-delete',`data-id="${f.id}"`)}</div></article>`;}).join('')}</div>`;}
 function flashStats(uid){const s=flashScore(data('flashcard_runs').filter(r=>r.student_id===uid));return `<div class="revision-summary flash-summary"><article><span>Respondidos</span><strong>${s.total}</strong><small>cartões revisados</small></article><article><span>Acertei</span><strong>${s.correct}</strong><small>${s.total?Math.round(s.correct/s.total*100):0}% de acertos</small></article><article><span>Retomar</span><strong>${s.wrong+s.forgot}</strong><small>${s.wrong} erros · ${s.forgot} não lembrados</small></article></div>`;}
 function runDialog(){const card=run.cards.find(c=>!run.answers[c.id]),count=Object.keys(run.answers).length,topic=state.topics.find(t=>syllabusKey(t)===run.topic_key);if(!card){const stats=flashScore([run]);modal('Revisão concluída',`<div class="review-finish"><span class="eyebrow">${e(topic?.subject||'Flashcards')} · ${e(topic?.title||'Assunto')}</span><h3>${stats.correct} de ${stats.total} cartões lembrados</h3><progress max="${Math.max(1,stats.total)}" value="${stats.correct}"></progress><p>${stats.wrong} erros · ${stats.forgot} não lembrados. O histórico e o edital foram atualizados.</p><div class="actions"><a class="btn" href="#painel/revisoes">Voltar às revisões</a>${btn('Ver plano de hoje','study-back','','primary')}</div></div>`);return;}modal(`${e(topic?.subject||'Flashcards')} · ${count+1} de ${run.cards.length}`,`<article class="flash-face"><div><span class="eyebrow">${e(topic?.title||'Revisão do assunto')}</span><progress max="${run.cards.length}" value="${count}"></progress></div><span class="eyebrow">Responda mentalmente antes de revelar</span><h3>${e(card.front)}</h3>${revealed?`<div class="flash-answer">${e(card.back)}</div><p class="muted">Como foi lembrar desta resposta?</p><div class="actions">${btn('Acertei','flash-answer','data-choice="correct"','primary')}${btn('Errei','flash-answer','data-choice="wrong"')}${btn('Não lembrei','flash-answer','data-choice="forgot"')}</div>`:btn('Mostrar resposta','flash-reveal','','primary')}</article>`);}
 function historyHTML(uid,key){const topic=state.topics.find(t=>syllabusKey(t)===key),logs=data('study_logs').filter(l=>l.student_id===uid&&(l.topic_key===key||(!l.topic_key&&l.subject===topic?.subject&&l.topic===topic?.title))),sessions=data('study_sessions').filter(s=>s.student_id===uid&&s.topic_key===key),studies=data('method_studies').filter(s=>s.student_id===uid&&s.topic_key===key&&s.studied_at),events=data('topic_events').filter(s=>s.student_id===uid&&s.topic_key===key),runs=data('flashcard_runs').filter(r=>r.student_id===uid&&r.topic_key===key),first=[...studies.map(s=>s.studied_at),...events.filter(x=>x.kind==='study').map(s=>s.created_at)].sort()[0];const entries=[...logs.map(l=>({at:l.created_at,text:l.source+' · '+l.total+' questões, '+l.correct+' acertos, '+(l.total-l.correct)+' erros'+(Number(l.minutes)?' · '+durationText(Number(l.minutes)*60):'')+(l.notes?' · '+l.notes:'')})),...runs.map(r=>{const s=flashScore([r]);return{at:r.completed_at||r.started_at,text:'Flashcards: '+s.correct+' acertos, '+s.wrong+' erros, '+s.forgot+' não lembrados'+(!r.completed_at?' (em andamento)':'')};}),...events.filter(x=>x.kind!=='flashcards').map(x=>({at:x.created_at,text:({study:'Estudo concluído',summary:'Resumo concluído',questions:'Questões registradas',review:'Revisão concluída'}[x.kind]||x.kind)}))].sort((a,b)=>b.at.localeCompare(a.at));return `<h3>${e(topic?.subject)} · ${e(topic?.title||key)}</h3><p>Primeiro estudo: ${first?new Date(first).toLocaleString('pt-BR'):'Ainda não concluído'}</p><p>Tempo estudado: ${durationText(logs.reduce((a,l)=>a+Number(l.minutes||0),0)*60)}</p><p>${logs.reduce((a,l)=>a+l.total,0)} questões · ${logs.reduce((a,l)=>a+l.correct,0)} acertos · ${logs.reduce((a,l)=>a+l.total-l.correct,0)} erros</p><ol class="topic-timeline">${entries.map(x=>`<li><time>${new Date(x.at).toLocaleString('pt-BR')}</time><p>${e(x.text)}</p></li>`).join('')||'<li>Nenhum registro neste assunto.</li>'}</ol>`;}
 function dayHistory(uid){return `<details class="card"><summary>Histórico dos dias do plano</summary>${data('cycle_days').filter(d=>d.student_id===uid).sort((a,b)=>b.started_at.localeCompare(a.started_at)).map(d=>{const logs=data('study_logs').filter(l=>l.cycle_id===d.cycle_id&&l.plan_day===d.day),c=data('cycles').find(c=>c.id===d.cycle_id);return `<article><h3>${e(c?.title)} · ${planLabel(d.day)}</h3><p>Início: ${new Date(d.started_at).toLocaleString('pt-BR')} · Conclusão: ${d.completed_at?new Date(d.completed_at).toLocaleString('pt-BR'):'Em andamento'}</p><p>${durationText(logs.reduce((a,l)=>a+Number(l.minutes),0)*60)} · ${logs.reduce((a,l)=>a+l.total,0)} questões</p><p>Assuntos concluídos: ${c?.blocks.filter(b=>blockDay(b,c)===d.day&&visibleSteps(c,b,state.data).every(st=>getStudy(c,b)?.flags?.[st.id])).map(b=>e(b.topic)).join(', ')||'Nenhum'}</p></article>`;}).join('')||'<p>Nenhum dia iniciado.</p>'}</details>`;}
 async function submit(form,fd){const v=Object.fromEntries(fd);if(form.id==='study-start-form'){guardWrite();session=await api.rpc('study_timer',{payload:{action:'create',cycle_id:state.studyTarget.cycle,block_id:state.studyTarget.block,minutes:v.duration==='custom'?+v.custom:+v.duration,focus:+v.focus,rest:+v.rest}});syncedAt=Date.now();await loadData();showWorkspace();return true;}if(form.id==='flashcard-form'){guardWrite();await api.save('flashcards',{topic_key:v.topic_key,front:v.front.trim(),back:v.back.trim(),review_keys:fd.getAll('review_keys')},form.dataset.id||undefined);cardEdit=null;await loadData();renderView();notify('Flashcard salvo e vinculado ao assunto.');return true;}return false;}
 async function click(el){const a=el.dataset.action;if(a==='study-open'){const c=data('cycles').find(c=>c.id===el.dataset.cycle),b=c?.blocks.find(b=>b.id===el.dataset.block);if(!b)throw Error('Assunto não encontrado.');await open(c,b);return true;}
 if(a==='study-return'){restore();if(!session)throw Error('Nenhuma sessão em andamento.');state.studyTarget={cycle:session.cycle_id,block:session.block_id};showWorkspace();return true;}
 if(a==='study-close'){document.querySelector('#study-dialog')?.remove();notify('Janela fechada.','info');return true;}
 if(a==='study-back'){document.querySelector('#study-dialog')?.remove();location.hash='#painel/ciclos';notify('Plano de estudos aberto.','info');return true;}
 if(a.startsWith('timer-')){await timerCommand(a.slice(6));document.querySelector('#study-dialog')?.remove();return true;}
 if(a==='study-advance'||a==='advance-study-day'){guardWrite();const r=await api.rpc('advance_method_day',{cycle_uuid:el.dataset.cycle});await loadData();state.boardStart=r.day;renderView();notify(r.message||'Próximo dia liberado.');return true;}
 if(a==='study-material'){guardWrite();const r=data('resources').find(r=>r.id===el.dataset.id);state.studyMaterial={...r,url:r.storage_path?await api.assetUrl(r.storage_path):r.url};await api.save('resource_views',{student_id:state.profile.id,resource_id:r.id});renderView();notify('Conteúdo recomendado aberto.');return true;}
 if(a==='topic-history'){modal('Histórico do assunto',historyHTML(el.dataset.student||state.profile.id,el.dataset.topic));notify('Histórico do assunto aberto.','info');return true;}
 if(a==='flash-start'){guardWrite();run=await api.rpc('flash_action',{payload:{action:'start',...(el.dataset.review?{review_id:el.dataset.review}:{cycle_id:el.dataset.cycle,block_id:el.dataset.block,step_id:el.dataset.stage})}});revealed=false;runDialog();notify('Flashcards do assunto abertos.','info');return true;}
 if(a==='flash-reveal'){revealed=true;runDialog();notify('Resposta revelada. Registre como foi.','info');return true;}
 if(a==='flash-answer'){guardWrite();const card=run.cards.find(c=>!run.answers[c.id]);if(!card||!revealed)throw Error('Confira a resposta antes de registrar.');run=await api.rpc('flash_action',{payload:{action:'answer',run_id:run.id,card_id:card.id,choice:el.dataset.choice}});revealed=false;await loadData();renderView();runDialog();notify(run.completed_at?'Revisão concluída. Desempenho e edital atualizados.':'Resposta salva.');return true;}
 if(a==='flash-clear'){cardEdit=null;renderView();notify('Formulário limpo.','info');return true;}
 if(a==='flash-edit'){cardEdit=data('flashcards').find(f=>f.id===el.dataset.id);const t=state.topics.find(t=>syllabusKey(t)===cardEdit.topic_key);state.cardCareer=t.career;state.cardSubject=t.subject;renderView();document.querySelector('#flashcard-form')?.scrollIntoView({behavior:'smooth'});notify('Flashcard aberto para edição.','info');return true;}
 if(a==='flash-delete'){if(!confirm('Excluir este flashcard? Resultados já registrados serão preservados.')){notify('Exclusão cancelada.','info');return true;}guardWrite();await api.remove('flashcards',el.dataset.id);await loadData();renderView();notify('Flashcard excluído.');return true;}return false;}
 function change(el){if(['card_career','card_subject'].includes(el.name)){const f=document.querySelector('#flashcard-form');if(f){const v=Object.fromEntries(new FormData(f));cardEdit={...(cardEdit||{}),front:v.front,back:v.back,review_keys:new FormData(f).getAll('review_keys')};}if(el.name==='card_career'){state.cardCareer=el.value;state.cardSubject=null;}else state.cardSubject=el.value;renderView();notify('Assuntos do edital atualizados.','info');}}
 async function pauseOnLeave(){if(session?.status==='running')try{await timerCommand('pause');}catch{session.status='paused';}}
 function reset(){session=null;run=null;state.studyTarget=null;state.studyMaterial=null;document.querySelector('#timer-chip')?.remove();document.querySelector('#study-dialog')?.remove();}
 return {reset,page,dashboard,topicCard,progress,flashPage,flashStats,dayHistory,historyHTML,submit,click,change,afterRender,tick,pauseOnLeave};
}
